static void test_mont_mul(void) {
    TEST_SUITE("p256_scalar_mont_mul — a*b*R^-1 mod n");
    for (int i = 0; i < NMM; i++) {
        uint64_t a[4], b[4], out[4];
        uint8_t outb[32];
        p256_fe_frombytes(a, MMS[i].a);
        p256_fe_frombytes(b, MMS[i].b);
        p256_scalar_mont_mul(out, a, b);
        p256_fe_tobytes(outb, out);
        ASSERT_EQ("a*b*R^-1 mod n", 0, memcmp(outb, MMS[i].want, 32));
    }

    // out may alias either input: the routine loads both operands
    // into registers up front and stores only at the end.
    for (int i = 0; i < NMM; i++) {
        uint64_t a[4], b[4];
        uint8_t outb[32];
        p256_fe_frombytes(a, MMS[i].a);
        p256_fe_frombytes(b, MMS[i].b);
        p256_scalar_mont_mul(a, a, b);
        p256_fe_tobytes(outb, a);
        ASSERT_EQ("aliasing out == a", 0, memcmp(outb, MMS[i].want, 32));
        p256_fe_frombytes(a, MMS[i].a);
        p256_fe_frombytes(b, MMS[i].b);
        p256_scalar_mont_mul(b, a, b);
        p256_fe_tobytes(outb, b);
        ASSERT_EQ("aliasing out == b", 0, memcmp(outb, MMS[i].want, 32));
        p256_fe_frombytes(a, MMS[i].a);
        p256_scalar_mont_mul(a, a, a);
        p256_fe_tobytes(outb, a);
        uint64_t sq[4], a2[4];
        p256_fe_frombytes(a2, MMS[i].a);
        p256_scalar_mont_mul(sq, a2, a2);
        uint8_t sqb[32];
        p256_fe_tobytes(sqb, sq);
        ASSERT_EQ("aliasing out == a == b", 0, memcmp(outb, sqb, 32));
    }
}

int main(void) {
    test_mont_mul();
    test_summary();
    return 0;
}
